<template><view class="page"><view class="cover"><text @tap="back">‹</text><text>分享 ···</text></view><view class="profile"><view class="avatar">遇</view><b>{{profile.nickname||name}} <i>♀ 24</i></b><small>{{profile.city}} · 在线 · 认证用户</small><p>{{profile.bio}}</p><view class="tags"><text v-for="tag in profile.tags.split(/\\s+/)" :key="tag">{{tag}}</text></view><view class="stats"><view><b>128</b><small>关注</small></view><view><b>2.4k</b><small>喜欢</small></view><view><b>86</b><small>动态</small></view></view><button @tap="follow">{{followed?'已关注':'＋ 关注'}}</button><button class="chat" @tap="toChat">发消息</button></view><view class="section">她的生活 <small>最近动态</small></view><view class="posts"><view v-for="(p,n) in posts" :key="n" class="post">{{p.text}} <small>♡ {{p.likes}}</small></view><view v-if="!posts.length" class="post">还没有发布动态</view></view></view></template><script setup>import{ref}from'vue';const name=ref('小鱼'),followed=ref(false),profile=ref({nickname:'',city:'杭州',bio:'认真生活，慢慢遇见。喜欢旅行、咖啡和有趣的灵魂。',tags:'旅行 摄影 咖啡'}),posts=ref([]);try{const q=uni.getCurrentPages().slice(-1)[0]?.options||{};if(q.name)name.value=decodeURIComponent(q.name);const p=uni.getStorageSync('meet-profile');if(p)profile.value={...profile.value,...p};const ps=uni.getStorageSync('meet-posts');if(ps)posts.value=ps;const fs=uni.getStorageSync('meet-following')||[];followed.value=fs.includes(name.value)}catch(e){}function back(){uni.navigateBack()}function follow(){followed.value=!followed.value;const fs=uni.getStorageSync('meet-following')||[];const next=followed.value?[...new Set([...fs,name.value])]:fs.filter(x=>x!==name.value);uni.setStorageSync('meet-following',next)}function toChat(){uni.navigateTo({url:'/pages/chat/index?name='+encodeURIComponent(name.value)})}</script><style scoped lang="scss">.page{min-height:100vh;background:#f7f5fa;color:#332e40}.cover{height:210px;padding:28px 20px;display:flex;justify-content:space-between;color:white;background:linear-gradient(135deg,#9fbde9,#dba9d0 55%,#f2d4df);font-size:23px}.profile{position:relative;margin:-42px 16px 0;padding:58px 20px 20px;text-align:center;background:#fff;border-radius:24px;box-shadow:0 10px 35px #9387a51c}.avatar{position:absolute;top:-42px;left:calc(50% - 42px);width:84px;height:84px;border-radius:50%;border:5px solid white;background:linear-gradient(140deg,#d9eaff,#f4cbe8);display:grid;place-items:center;font-size:26px;color:#9c78b6}.profile b{font-size:22px}.profile i{font-size:12px;color:#dc75b3}.profile small{display:block;color:#aaa;font-size:11px;margin:8px}.profile p{font-size:13px;color:#777;line-height:1.7}.tags text{display:inline-block;background:#f7eff8;color:#a77bad;padding:6px 12px;border-radius:20px;margin:4px;font-size:11px}.stats{display:flex;justify-content:space-around;margin:20px 0}.stats b,.stats small{display:block}.stats small{margin-top:4px}.profile button{display:inline-block;width:46%;margin:0 1%;border:0;border-radius:22px;background:linear-gradient(100deg,#f39bc4,#b39af0);color:white;font-size:13px}.profile .chat{background:#f3edf7;color:#9b78ad}.section{padding:24px 20px 12px;font-weight:800}.section small{float:right;color:#aaa;font-weight:400}.posts{padding:0 16px}.post{background:white;border-radius:16px;padding:20px;margin-bottom:10px;font-size:13px;color:#696171}.post small{float:right;color:#d77eb3}</style>